class Solution:
    def minOperations(self, word1: str, word2: str) -> int:
        n = len(word1)
        INF = float('inf')
        dp = [[INF]*n for _ in range(n)]
        for i in range(n):
            dp[i][i] = 0 if word1[i] == word2[i] else 1
        for l in range(1, n):
            for i in range(n - l):
                j = i + l
                best = min(dp[i][k] + dp[k+1][j] for k in range(i, j))
                inner = dp[i+1][j-1] if l > 1 else 0
                a, b, c, d = word1[i], word1[j], word2[i], word2[j]
                if a == c and b == d:
                    best = min(best, inner)
                if a == d and b == c:
                    best = min(best, 1 + inner)
                if a == d or b == c:
                    best = min(best, 2 + inner)
                dp[i][j] = best
        g = [INF]*(n+1)
        g[0] = 0
        for j in range(n):
            for i in range(j+1):
                g[j+1] = min(g[j+1], g[i] + dp[i][j])
        return g[n]

