class Solution {
public:
    int minOperations(string word1, string word2) {
        int n = word1.size();
        const int INF = INT_MAX / 2;
        vector<vector<int>> dp(n, vector<int>(n, INF));
        for (int i = 0; i < n; i++) dp[i][i] = word1[i] == word2[i] ? 0 : 1;
        for (int l = 1; l < n; l++)
            for (int i = 0; i + l < n; i++) {
                int j = i + l, best = INF;
                for (int k = i; k < j; k++) best = min(best, dp[i][k] + dp[k+1][j]);
                int inner = l > 1 ? dp[i+1][j-1] : 0;
                char a = word1[i], b = word1[j], c = word2[i], d = word2[j];
                if (a == c && b == d) best = min(best, inner);
                if (a == d && b == c) best = min(best, 1 + inner);
                if (a == d || b == c) best = min(best, 2 + inner);
                dp[i][j] = best;
            }
        vector<int> g(n + 1, INF); g[0] = 0;
        for (int j = 0; j < n; j++)
            for (int i = 0; i <= j; i++)
                g[j+1] = min(g[j+1], g[i] + dp[i][j]);
        return g[n];
    }
};

