class Solution {
    public int minOperations(String word1, String word2) {
        int n = word1.length();
        int INF = Integer.MAX_VALUE / 2;
        int[][] dp = new int[n][n];
        for (int[] row : dp) java.util.Arrays.fill(row, INF);
        for (int i = 0; i < n; i++) dp[i][i] = word1.charAt(i) == word2.charAt(i) ? 0 : 1;
        for (int l = 1; l < n; l++)
            for (int i = 0; i + l < n; i++) {
                int j = i + l, best = INF;
                for (int k = i; k < j; k++) best = Math.min(best, dp[i][k] + dp[k+1][j]);
                int inner = l > 1 ? dp[i+1][j-1] : 0;
                char a = word1.charAt(i), b = word1.charAt(j), c = word2.charAt(i), d = word2.charAt(j);
                if (a == c && b == d) best = Math.min(best, inner);
                if (a == d && b == c) best = Math.min(best, 1 + inner);
                if (a == d || b == c) best = Math.min(best, 2 + inner);
                dp[i][j] = best;
            }
        int[] g = new int[n + 1];
        java.util.Arrays.fill(g, INF); g[0] = 0;
        for (int j = 0; j < n; j++)
            for (int i = 0; i <= j; i++)
                g[j+1] = Math.min(g[j+1], g[i] + dp[i][j]);
        return g[n];
    }
}

