var minOperations = function(word1, word2) {
    const n = word1.length, INF = 1e9;
    const dp = Array.from({length: n}, () => Array(n).fill(INF));
    for (let i = 0; i < n; i++) dp[i][i] = word1[i] === word2[i] ? 0 : 1;
    for (let l = 1; l < n; l++)
        for (let i = 0; i + l < n; i++) {
            const j = i + l;
            let best = INF;
            for (let k = i; k < j; k++) best = Math.min(best, dp[i][k] + dp[k+1][j]);
            const inner = l > 1 ? dp[i+1][j-1] : 0;
            const a = word1[i], b = word1[j], c = word2[i], d = word2[j];
            if (a === c && b === d) best = Math.min(best, inner);
            if (a === d && b === c) best = Math.min(best, 1 + inner);
            if (a === d || b === c) best = Math.min(best, 2 + inner);
            dp[i][j] = best;
        }
    const g = Array(n + 1).fill(INF); g[0] = 0;
    for (let j = 0; j < n; j++)
        for (let i = 0; i <= j; i++)
            g[j+1] = Math.min(g[j+1], g[i] + dp[i][j]);
    return g[n];
};
